using System;using System.IO;using UnityEditor;using UnityEngine;
// Local generated review assets only. No originals are overwritten or committed.
public static class OriginalDenseLocalArtifactStage {
 [Serializable]public class Item {public string source,asset,sha256;}
 [Serializable]public class Packet {public Item[] files;}
 public static void Stage(){string manifest=Environment.GetEnvironmentVariable("LIGHTFIGHT_DENSE_LOCAL_INPUTS");if(string.IsNullOrEmpty(manifest))throw new Exception("Set LIGHTFIGHT_DENSE_LOCAL_INPUTS to the local generated-artifact manifest; these large artifacts must stay outside raw git.");var packet=JsonUtility.FromJson<Packet>(File.ReadAllText(manifest));foreach(var item in packet.files){if(!item.asset.StartsWith("Assets/NativeDense/",StringComparison.Ordinal)||item.asset.Contains(".."))throw new Exception("Review cache path required");if(!File.Exists(item.source))throw new FileNotFoundException("Local canonical artifact missing; reproduce Blender/Unity import gates first",item.source);using(var sha=System.Security.Cryptography.SHA256.Create())using(var stream=File.OpenRead(item.source)){string hash=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();if(hash!=item.sha256)throw new Exception("Local artifact changed: "+item.source);}Directory.CreateDirectory(Path.GetDirectoryName(item.asset));if(File.Exists(item.asset)&&Path.GetFullPath(item.source)!=Path.GetFullPath(item.asset))throw new Exception("Refusing to overwrite existing review asset: "+item.asset);if(Path.GetFullPath(item.source)!=Path.GetFullPath(item.asset))File.Copy(item.source,item.asset,false);}AssetDatabase.Refresh();Debug.Log("AGENT_RESULT local original-density review artifacts staged; generated Assets/NativeDense cache must be ignored by raw git");}
}
